if (isNaN(value)) { ... } إظهار الحل نسخ الكود جرّب المثال <!DOCTYPE html>
<html lang="ar" dir="rtl">
<body>
  <input id="age" placeholder="أدخل العمر">
  <button onclick="check()">تحقق</button>
  <p id="result"></p>

  <script>
    function check() {
      let v = document.getElementById("age").value.trim();
      if (v === "") {
        document.getElementById("result").innerHTML = "⚠️ الحقل فارغ";
      } else if (isNaN(v)) {
        document.getElementById("result").innerHTML = "❌ أدخل رقمًا فقط";
