              background:#f9f9f9;cursor:pointer;">
    مرّر الفأرة هنا
  </div>
  <p id="r"></p>

  <script>
    function enter() {
      document.getElementById("r").innerHTML = "🖱️ الفأرة داخل المربع";
    }
    function leave() {
      document.getElementById("r").innerHTML = "👋 الفأرة خارج المربع";
    }
  </script>
</body>
</html> تدريب 5 متقدم كبّر صورة عند الضغط على زر، وأوقف التكبير عند حد معين (200px). نسخ الكود 💡 تلميح نسخ الكود جرّب المثال let img = document.getElementById("img");
if (img.width < 200) {
  img.width += 20;
} إظهار الحل نسخ الكود جرّب المثال <!DOCTYPE html>
<html lang="ar" dir="rtl">
<body>
  <img id="img"
       src="https://picsum.photos/100"
       width="100"
       style="border-radius:8px;">
  <br><br>
  <button onclick="grow()">كبّر الصورة</button>
  <button onclick="shrink()">صغّر الصورة</button>
  <p id="sizeInfo">الحجم الحالي: 100px</p>

  <script>
    function grow() {
      let img = document.getElementById("img");
      if (img.width < 200) {
        img.width += 20;
        document.getElementById("sizeInfo").innerHTML = "الحجم الحالي: " + img.width + "px";
      } else {
        document.getElementById("sizeInfo").innerHTML = "⚠️ وصلنا للحد الأقصى (200px)";
      }
    }
    function shrink() {
      let img = document.getElementById("img");
      if (img.width > 60) {
        img.width -= 20;
        document.getElementById("sizeInfo").innerHTML = "الحجم الحالي: " + img.width + "px";
      }
    }
  </script>
</body>
</html> مشروع مصغر متقدم ابنِ صفحة تجمع: حقل اسم + تحقق بسيط + زر + رسالة نتيجة + عنصر يتحرك أو يتغير حجمه. إظهار نموذج الحل نسخ الكود جرّب المثال <!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
  <meta charset="UTF-8">
  <style>
    body { font-family: sans-serif; padding: 20px; }
    #box {
      width: 80px; height: 80px;
      background: teal; border-radius: 8px;
      transition: all 0.4s;
      margin-top: 16px;
