echo $book["title"]; حدّد الدرس كمكتمل الدرس 3 من 12 → الدرس السابق الدرس التالي ←

4. التعابير والعوامل التعبير ينتج قيمة. من العوامل الحسابية + و- و* و/ و%، والإسناد = و+=، والمقارنة === و!== و>=، والمنطقية && و|| و!، والربط النصي نقطة. الأقواس توضح ترتيب التنفيذ. نسخ الكود <?php
$total = 20 + 5 * 2;     // 30
$grouped = (20 + 5) * 2; // 50
$mark = 70;
$passed = $mark >= 50 && $mark <= 100;
echo "المجموع: " . $total;
var_dump(5 === "5");   // false عوامل إضافية يوردها الكتاب ++ و-- للزيادة والنقصان، و& و| و^ و<< و>> لعمليات البت. يجمع + مصفوفتين مع الاحتفاظ بمفاتيح اليسرى. instanceof يفحص نوع كائن. يورد الكتاب @ للتحكم برسائل الخطأ وbackticks لتنفيذ أوامر نظام؛ افهم دورهما ولا تستخدمهما لإخفاء أخطاء التطبيق أو لتنفيذ إدخال المستخدم. نستخدم الاستثناءات لمعالجة أخطاء القاعدة. طبّق بنفسك توقع ناتج 10 % 3 ونتيجة المقارنة 10 === "10". الحل المقترح الباقي 1، والمقارنة false لاختلاف النوع. حدّد الدرس كمكتمل الدرس 4 من 12 → الدرس السابق الدرس التالي ←

5. الشروط والحلقات وبنى التحكم استخدم if وelseif وelse لاتخاذ قرار، وswitch للاختيار بين حالات. while يفحص الشرط قبل التكرار، وdo…while ينفذ مرة على الأقل، وfor مناسب لعدد معلوم، وforeach لمرور عناصر المصفوفة. نسخ الكود <?php
$marks = [40, 75, 90];
foreach ($marks as $mark) {
    if ($mark >= 50) {
        echo "ناجح: $mark<br>";
    } else {
        echo "بحاجة إلى مراجعة: $mark<br>";
    }
}
for ($i = 1; $i <= 3; $i++) {
    echo $i . " ";
} break يوقف الحلقة أو switch، وcontinue يتجاوز بقية التكرار الحالي. return يعيد نتيجة الدالة وينهيها. declare يحدد توجيهات تنفيذ مثل strict_types. يورد الكتاب goto والصياغة البديلة if: … endif؛ في التطبيقات هنا نستخدم بنى واضحة دون القفز بين السطور. طبّق بنفسك اطبع الأعداد الزوجية من 2 إلى 10 باستخدام for. الحل المقترح نسخ الكود <?php
for ($i = 2; $i <= 10; $i += 2) {
    echo $i . " ";
} حدّد الدرس كمكتمل الدرس 5 من 12 → الدرس السابق الدرس التالي ←

6. الدوال وتقسيم الملفات الدالة تجمع مهمة قابلة لإعادة الاستخدام. المعاملات مدخلات، وreturn يعيد الناتج. توجد دوال مضمّنة وأخرى تعرفها بنفسك، ويمكن إسناد دالة مجهولة إلى متغير أو استدعاء دالة باسم محفوظ في متغير. نسخ الكود <?php
function average(array $marks): float {
    if (count($marks) === 0) {
        return 0;
    }
    return array_sum($marks) / count($marks);
}
echo average([70, 80, 90]); // 80
$double = function ($value) { return $value * 2; };
echo $double(4); // 8 include وrequire يضمان ملفاً آخر؛ فشل require يوقف التنفيذ عادة، بينما include يصدر تحذيراً ويمكن أن يستمر. الصيغتان include_once وrequire_once تمنعان تكرار التضمين. استخدم مساراً ثابتاً مثل require_once __DIR__ . "/db.php"، ولا تأخذ مسار الملف من الزائر. طبّق بنفسك اكتب دالة تعيد ناجح إذا كانت العلامة 50 فأكثر. الحل المقترح نسخ الكود <?php
function result(int $mark): string {
    return $mark >= 50 ? "ناجح" : "راسب";
}
echo result(65); حدّد الدرس كمكتمل الدرس 6 من 12 → الدرس السابق الدرس التالي ←

7. استقبال بيانات النماذج يرسل GET قيماً في العنوان، وPOST يرسلها في جسم الطلب. POST وحده لا يشفر البيانات. تحقق في الخادم حتى إذا أضفت تحققاً في JavaScript. htmlspecialchars يعالج النص عند عرضه داخل HTML؛ ولا يحل محل الاستعلامات المحضرة. نسخ الكود <!-- form.html -->
<form action="welcome.php" method="post">
  <label>الاسم <input name="name" required maxlength="100"></label>
  <button>إرسال</button>
</form>

<!-- welcome.php -->
<?php
$raw = $_POST["name"] ?? "";
$name = is_string($raw) ? trim($raw) : "";
if ($name === "" || strlen($name) > 400) {
    http_response_code(422);
    exit("أدخل اسماً صالحاً");
}
echo "مرحباً " . htmlspecialchars($name, ENT_QUOTES, "UTF-8"); طبّق بنفسك أرسل اسماً فارغاً بعد تعطيل required. ماذا يجب أن يحدث؟ الحل المقترح يرفض الخادم القيمة الفارغة. التحقق في المتصفح يساعد المستخدم لكنه لا يكفي لضمان صحة البيانات. حدّد الدرس كمكتمل الدرس 7 من 12 → الدرس السابق الدرس التالي ←

8. SQL: إنشاء قاعدة وجدول قاعدة البيانات تحتوي جداول، والجدول يتكون من صفوف وأعمدة. المفتاح الأساسي يميز السجل، وAUTO_INCREMENT ينشئ معرفاً متزايداً. اختر utf8mb4 لدعم العربية. نسخ الكود CREATE DATABASE IF NOT EXISTS course1266
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE course1266;
CREATE TABLE IF NOT EXISTS students (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  mark INT NOT NULL
); نفذ الأوامر في أداة إدارة MySQL. DROP TABLE يحذف الجدول، وDROP DATABASE يحذف القاعدة ومحتوياتها؛ لا تحتاج إلى تشغيلهما لإتمام المختبر. طبّق بنفسك لماذا لا نستخدم اسم الطالب مفتاحاً أساسياً؟ الحل المقترح قد تتكرر الأسماء أو تتغير. المعرف الرقمي يوفر قيمة مستقلة تميز كل سجل. حدّد الدرس كمكتمل الدرس 8 من 12 → الدرس السابق الدرس التالي ←

9. SQL: الإضافة والاستعلام والتعديل والحذف ابدأ بقاعدة تدريب فقط. WHERE يحدد السجلات المستهدفة؛ غيابه في UPDATE أو DELETE يؤثر في كل السجلات. ORDER BY يرتب النتائج، وLIMIT يحدد عددها. نسخ الكود INSERT INTO students (name, mark) VALUES ('ليان', 85), ('عمر', 70);
SELECT id, name, mark FROM students ORDER BY id;
SELECT name, mark FROM students WHERE mark >= 80 ORDER BY mark DESC LIMIT 5;
UPDATE students SET mark = 90 WHERE id = 1;
DELETE FROM students WHERE id = 2; طبّق بنفسك اعرض الطلاب الناجحين مرتبين حسب العلامة تنازلياً. الحل المقترح نسخ الكود SELECT id, name, mark FROM students
WHERE mark >= 50 ORDER BY mark DESC, id ASC; حدّد الدرس كمكتمل الدرس 9 من 12 → الدرس السابق الدرس التالي ←

10. ربط PHP بقاعدة MySQL PDO وMySQLi طريقتان للربط. MySQLi مخصص لـMySQL، بينما PDO يوفر واجهة تتعامل مع عدة محركات عبر برامج تشغيل مختلفة. نستخدم PDO واستعلامات محضرة لتمرير القيم منفصلة عن نص SQL. نسخ الكود <?php
// db.php - بيانات بيئتك المحلية
$pdo = new PDO(
    "mysql:host=127.0.0.1;dbname=course1266;charset=utf8mb4",
    "course_student",
    "change-this-local-password",
    [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
     PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
     PDO::ATTR_EMULATE_PREPARES => false]
); نسخ الكود <?php
require_once __DIR__ . "/db.php";
$stmt = $pdo->prepare("INSERT INTO students (name, mark) VALUES (:name, :mark)");
$stmt->execute(["name" => "ليان", "mark" => 85]);
$query = $pdo->prepare("SELECT id, name, mark FROM students WHERE mark >= ? ORDER BY id LIMIT 10");
$query->execute([50]);
foreach ($query as $student) {
    echo htmlspecialchars($student["name"], ENT_QUOTES, "UTF-8") . "<br>";
} أنشئ مستخدم قاعدة محلياً يملك صلاحيات SELECT وINSERT وUPDATE وDELETE على قاعدة التدريب، ثم عدّل db.php. تشرح تعليمات المشروع ذلك. إذا فشل الاتصال، تحقق من تشغيل الخدمة واسم القاعدة والمنفذ وبيانات المستخدم وامتداد pdo_mysql. مرجع PHP الرسمي للاستعلامات المحضرة حدّد الدرس كمكتمل الدرس 10 من 12 → الدرس السابق الدرس التالي ←

